/** `elementum_agent` + one tool resource per implemented tool, in ei's dialect. */
export function agentToTf(entity, ctx) {
    if (entity.kind !== "agent") {
        throw new EntityTfError(`agentToTf expects kind "agent"; got "${entity.kind}" (refName "${entity.refName}")`);
    }
    const payload = entity.payload;
    const elementum = payload?.agent?.elementum;
    const bedrock = payload?.agent?.bedrock;
    if (payload === null || typeof payload !== "object" || (elementum === undefined && bedrock === undefined)) {
        throw new EntityTfError(`agent "${entity.refName}" has no agent payload — was it built with agent or bedrockAgent?`);
    }
    // The bag key IS the label (the stable naming contract) — the agent's
    // refName comes from its file name, exactly like an app's.
    const agentBareTfLabel = tsLabelToTfLabel(entity.refName);
    const tfLabel = appScopedResourceLabel(ctx.appTfLabel, agentBareTfLabel);
    if (bedrock !== undefined) {
        const name = bedrock.name ?? "";
        const where = `agent "${name}"`;
        const attrs = {
            app_id: expr.resourceAttr(APP_RESOURCE_TYPE, ctx.appTfLabel, ["id"]),
            type: "bedrock",
            name,
            description: bedrock.description ?? "",
            instructions: bedrock.instructions ?? "",
            bedrock_agent_arn: bedrock.agentAliasArn ?? "",
        };
        if (bedrock.firstMessage !== undefined) {
            attrs["first_message"] = bedrock.firstMessage;
        }
        const connector = bedrock.aiProviderConnectorId;
        if (connector === undefined) {
            ctx.diagnostics.push(`${where}: no provider connector token for bedrock agent`);
        }
        else {
            const tsLabel = connector.parent !== undefined
                ? `${connector.parent}.${connector.refName ?? ""}`
                : (connector.refName ?? "");
            const resolved = ctx.orgRefs.byTsLabel(CONNECTOR_ORG_BAG, tsLabel);
            if (resolved === undefined) {
                ctx.diagnostics.push(`${where}: connector token "${tsLabel}" is not in the org catalog — re-run \`elementum pull org --data-only\``);
            }
            else {
                attrs["ai_provider_connector_id"] = expr.dataAttr("elementum_ai_provider_connector", resolved.tfLabel, ["id"]);
            }
        }
        return {
            blocks: [{ kind: "resource", type: AGENT_RESOURCE_TYPE, label: tfLabel, attrs }],
            address: `${AGENT_RESOURCE_TYPE}.${tfLabel}`,
        };
    }
    if (elementum === undefined) {
        throw new EntityTfError(`agent "${entity.refName}" has no agent payload — was it built with agent or bedrockAgent?`);
    }
    const name = elementum.name ?? "";
    const where = `agent "${name}"`;
    const attrs = {
        app_id: expr.resourceAttr(APP_RESOURCE_TYPE, ctx.appTfLabel, ["id"]),
        name,
        description: elementum.description ?? "",
        instructions: elementum.instructions ?? "",
    };
    if (elementum.firstMessage !== undefined)
        attrs["first_message"] = elementum.firstMessage;
    if (elementum.maxLength !== undefined)
        attrs["max_tokens"] = elementum.maxLength;
    if (elementum.runAs !== undefined) {
        const value = runAsValue(elementum.runAs, where, ctx.diagnostics);
        if (value !== undefined)
            attrs["run_as"] = value;
    }
    if (elementum.agentAuthentication !== undefined) {
        attrs["jwt_authentication"] = jwtAuthenticationValue(elementum.agentAuthentication);
    }
    if (elementum.conversationIdleTimeout !== undefined)
        attrs["conversation_idle_timeout"] = elementum.conversationIdleTimeout;
    if (elementum.a2aStreaming !== undefined)
        attrs["a2a_streaming"] = elementum.a2aStreaming;
    if (elementum.a2aCreateRecordEnabled !== undefined)
        attrs["a2a_create_record_enabled"] = elementum.a2aCreateRecordEnabled;
    if (elementum.startingActions !== undefined) {
        const value = startingActionsValue(elementum.startingActions, where, ctx.diagnostics);
        if (value !== undefined)
            attrs["starting_actions"] = value;
    }
    const connector = elementum.aiProviderConnectorId;
    if (connector === undefined) {
        ctx.diagnostics.push(`${where}: no connector token — the platform will pick a default model`);
    }
    else {
        const tsLabel = connector.parent !== undefined ? `${connector.parent}.${connector.refName ?? ""}` : (connector.refName ?? "");
        const resolved = ctx.orgRefs.byTsLabel(CONNECTOR_ORG_BAG, tsLabel);
        if (resolved === undefined) {
            ctx.diagnostics.push(`${where}: connector token "${tsLabel}" is not in the org catalog — re-run \`elementum pull org --data-only\``);
        }
        else {
            attrs["ai_provider_connector_id"] = expr.dataAttr("elementum_ai_provider_connector", resolved.tfLabel, ["id"]);
        }
    }
    for (const knob of UNSUPPORTED_AGENT_KNOBS) {
        if (elementum[knob] !== undefined) {
            ctx.diagnostics.push(`${where}: ${knob} is not carried by the terraform path yet; dropped`);
        }
    }
    const skillAccess = elementum.skillAccessConfig;
    if (skillAccess !== undefined) {
        const mode = skillAccess.mode ?? "NONE";
        const skillAccessValue = { mode };
        if (skillAccess.skillIds !== undefined) {
            skillAccessValue["skill_ids"] = skillAccess.skillIds.map((t) => skillIdValue(t, ctx));
        }
        if (skillAccess.preloadedSkillIds !== undefined) {
            skillAccessValue["preloaded_skill_ids"] = skillAccess.preloadedSkillIds.map((t) => skillIdValue(t, ctx));
        }
        attrs["skill_access_config"] = skillAccessValue;
    }
    const blocks = [{ kind: "resource", type: AGENT_RESOURCE_TYPE, label: tfLabel, attrs }];
    for (const entry of payload.tools ?? []) {
        const tool = toolToTf(entry, {
            appRefName: ctx.appRefName,
            appTfLabel: ctx.appTfLabel,
            agentBareTfLabel,
            activeAutomationRefNames: ctx.activeAutomationRefNames,
            foreignAppRef: (l, n, ns) => ctx.orgRefs.foreignApp(l, n, ns),
            foreignElementRef: (l, n, ns) => ctx.orgRefs.foreignElement(l, n, ns),
            foreignAutomationRef: (l, n, owner) => {
                const ownerKind = owner.kind === "element" ? "element" : "app";
                const ownerRef = resolveForeignRef(ownerKind, { name: owner.name, namespace: owner.namespace }, ctx.orgRefs, ctx.diagnostics, `agent run-automation owner`);
                ctx.orgRefs.rawLookup("elementum_automation", l, n, {
                    app_id: ownerRef.value,
                });
            },
            foreignFieldRef: (t, l, o, n) => ctx.orgRefs.foreignField(t, l, o, n),
            workspaceAspects: ctx.workspaceAspects,
            serviceAccountRef: (_label, serviceAccountName) => serviceAccountValue(serviceAccountName, ctx),
            diagnostics: ctx.diagnostics,
        });
        if (tool !== undefined)
            blocks.push(tool.block);
    }
    // Board issue #294: two agents in the same app can legitimately both
    // author an a2a skill with the same display name — ei's own exporter
    // disambiguates that case with a numeric suffix rather than rejecting it
    // (see computeA2ASkillLabelSuffixes). A collision within THIS agent's own
    // a2aSkills list (the same name twice on one agent) is a real authoring
    // mistake, not a cross-agent scoping gap — still caught and dropped below.
    const a2aSkillLabelSuffixes = computeA2ASkillLabelSuffixes(ctx.siblingEntities ?? [entity]);
    const seenA2ASkillAddresses = new Set();
    payload.a2aSkills?.forEach((entry) => {
        const base = sanitizeName(entry.name ?? "");
        const skill = a2aSkillToTf(entry, {
            appTfLabel: ctx.appTfLabel,
            agentBareTfLabel,
            labelSuffix: a2aSkillLabelSuffixes.get(`${entity.refName}#${base}`) ?? "",
            diagnostics: ctx.diagnostics,
        });
        if (skill === undefined)
            return;
        if (seenA2ASkillAddresses.has(skill.address)) {
            ctx.diagnostics.push(`${where}: a2a skill "${entry.name}" collides with another skill's label (${skill.address}) — names must be unique per agent; dropped`);
            return;
        }
        seenA2ASkillAddresses.add(skill.address);
        blocks.push(skill.block);
    });
    return { blocks, address: `${AGENT_RESOURCE_TYPE}.${tfLabel}` };
}
